const BASE = 'https://raw.githubusercontent.com/joshinatasha196-ai/MIRA-Capstone/refs/heads/main/data/';
const files = [
  { dataset: 'tasks',       type: 'csv',  file: 'sample_task_board.csv' },
  { dataset: 'timeline',    type: 'csv',  file: 'project_timeline.csv' },
  { dataset: 'risks',       type: 'csv',  file: 'project_risks.csv' },
  { dataset: 'description', type: 'text', file: 'project_description.txt' }
];
return files.map(f => ({ json: { ...f, url: BASE + f.file } }));

// Node name: Parse all      Type: Code      Mode: Run Once for All Items
// Sits after ONE HTTP Request node (URL = {{ $json.url }}, Response Format = Text, field = data).
// Turns each downloaded file into rows tagged with "dataset", using the File list for the labels.
const list = $('File list').all().map(i => i.json);
const inputs = $input.all();
if (inputs.length !== list.length) throw new Error(`Expected ${list.length} downloads, got ${inputs.length}. Check the HTTP Request node.`);

const parseCSV = (raw) => {
  const text = String(raw || '').replace(/^\uFEFF/, '');
  const rows = []; let row = [], cur = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i + 1] === '"') { cur += '"'; i++; } else if (c === '"') q = false; else cur += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cur); cur = ''; }
    else if (c === '\n' || c === '\r') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cur); cur = ''; if (row.length > 1 || row[0] !== '') rows.push(row); row = []; }
    else cur += c;
  }
  if (cur !== '' || row.length) { row.push(cur); rows.push(row); }
  const header = (rows[0] || []).map(h => h.trim());
  return rows.slice(1).map(r => Object.fromEntries(header.map((h, i) => [h, (r[i] ?? '').trim()])));
};

const out = [];
inputs.forEach((item, i) => {
  const meta = list[i], raw = item.json.data;
  if (typeof raw !== 'string' || /^\s*<!DOCTYPE html/i.test(raw)) {
    throw new Error(`${meta.file} returned a web page, not the file. Check that its URL is a raw.githubusercontent.com URL.`);
  }
  if (meta.type === 'csv') {
    const rows = parseCSV(raw);
    if (!rows.length) throw new Error(`${meta.file} has no data rows`);
    rows.forEach(r => out.push({ json: { dataset: meta.dataset, ...r } }));
  } else {
    out.push({ json: { dataset: meta.dataset, data: raw } });
  }
});
return out;

// Node name: Config      Type: Code      Mode: Run Once for All Items
// One place for every tunable value. Change values here, not inside the other nodes.
return [{
  json: {
    as_of_date: '2026-04-22',          // fixed test date (do not use the system clock for evaluation)
    project_start_date: '2026-03-30',  // Monday of week 1, inferred from task due dates
    at_risk_days: 7,                   // "due soon" threshold for tasks and phases
    window_days: 14,                   // default look-ahead for upcoming milestones
    top_n_risks: 3,

    // Task label -> timeline phase number. Security and Compliance are cross-cutting (no phase).
    label_to_phase: {
      'Planning': 1, 'Analysis': 2, 'Use Cases': 3, 'Data Prep': 4, 'Model Dev': 4,
      'Pilot': 5, 'Evaluation': 6, 'Deployment': 7, 'Monitoring': 8
    },

    // Risk category (exact text from project_risks.csv) -> task labels that give evidence for it.
    // ASSUMPTION: please review. Categories with no clear label simply score 0.
    label_to_risk_category: {
      'Data Quality & Availability': ['Analysis', 'Data Prep'],
      'Integration Issues': ['Deployment', 'Pilot'],
      'Ethical & Legal Concerns': ['Compliance'],
      'Model Performance Drift': ['Monitoring', 'Evaluation'],
      'Security Vulnerabilities': ['Security']
    },

    // Each task counts once, at its highest applicable weight.
    risk_weights: { blocked: 3, overdue: 2, in_progress: 1 }
  }
}];

// Node name: Validate data      Type: Code      Mode: Run Once for All Items
// Checks the three CSVs before anything else runs. Route on {{ $json.ok }} with an IF node.
const tasks = $('Load tasks').all().map(i => i.json);
const phases = $('Load timeline').all().map(i => i.json);
const risks = $('Load risks').all().map(i => i.json);

const errors = [], warnings = [];
const need = {
  tasks: ['task_id', 'task_name', 'status', 'assignee', 'priority', 'sprint', 'due_date', 'labels', 'description'],
  phases: ['phase', 'phase_name', 'start_week', 'end_week', 'key_activities', 'milestones_deliverables'],
  risks: ['risk_id', 'category', 'risk_challenge', 'impact', 'mitigation_strategy']
};
const checkCols = (name, rows) => {
  if (!rows.length) { errors.push(`${name}: no rows found`); return; }
  const miss = need[name].filter(c => !(c in rows[0]));
  if (miss.length) errors.push(`${name}: missing columns ${miss.join(', ')}`);
};
checkCols('tasks', tasks); checkCols('phases', phases); checkCols('risks', risks);

const okStatus = ['Done', 'In Progress', 'Blocked', 'To Do'];
const seen = new Set();
for (const t of tasks) {
  if (seen.has(t.task_id)) errors.push(`duplicate task_id ${t.task_id}`);
  seen.add(t.task_id);
  if (!okStatus.includes(t.status)) errors.push(`${t.task_id}: unknown status "${t.status}"`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(t.due_date || '') || isNaN(Date.parse(t.due_date))) errors.push(`${t.task_id}: invalid due_date "${t.due_date}"`);
  if (!/^Sprint \d+$/.test(t.sprint || '')) warnings.push(`${t.task_id}: unexpected sprint value "${t.sprint}"`);
}
for (const p of phases) {
  if (!(Number(p.start_week) >= 1) || Number(p.end_week) < Number(p.start_week)) errors.push(`phase ${p.phase}: bad week range`);
}
const rid = new Set();
for (const r of risks) { if (rid.has(r.risk_id)) errors.push(`duplicate risk_id ${r.risk_id}`); rid.add(r.risk_id); }

return [{ json: {
  ok: errors.length === 0, has_task_data: tasks.length > 0,
  errors, warnings,
  counts: { tasks: tasks.length, phases: phases.length, risks: risks.length }
} }];

// Node name: Status engine      Type: Code      Mode: Run Once for All Items
// Needs upstream nodes named: Load tasks, Config. Optional: Gate (reads gate.sprint).
// Handles T5, T8, T10, T12. No LLM is involved.
const cfg = $('Config').first().json;
let gate = {};
try { const j = $('Gate').first().json; gate = j.output || j; } catch (e) { /* gate not run: whole project */ }

const tasks = $('Load tasks').all().map(i => i.json);
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];
const DAY = 86400000;
const day = s => Date.parse(s + 'T00:00:00Z');
const asOf = day(cfg.as_of_date);

const m = String(gate.sprint || '').match(/(\d+)/);
const sprint = m ? `Sprint ${parseInt(m[1], 10)}` : null;
const sprintFound = sprint ? tasks.some(t => t.sprint === sprint) : true;

const enrich = t => {
  const d = Math.round((day(t.due_date) - asOf) / DAY);
  const overdue = t.status !== 'Done' && d < 0;
  const dueSoon = t.status === 'To Do' && d >= 0 && d <= cfg.at_risk_days;
  const reasons = [];
  if (t.status === 'Blocked') reasons.push(`Blocked. Source note: ${t.description}`);
  if (overdue) reasons.push(`Overdue by ${-d} day(s): due ${t.due_date}, status ${t.status}`);
  if (dueSoon) reasons.push(`Due in ${d} day(s) and not started`);
  return { task_id: t.task_id, task_name: t.task_name, assignee: t.assignee, status: t.status,
    sprint: t.sprint, due_date: t.due_date, days_to_due: d, overdue, due_soon: dueSoon, reasons };
};
const countBy = rows => {
  const c = Object.fromEntries(STATUSES.map(s => [s, 0]));
  for (const r of rows) c[r.status] = (c[r.status] || 0) + 1;
  return c;
};

const all = tasks.map(enrich);
const scope = sprint ? all.filter(t => t.sprint === sprint) : all;
const inScopeIds = new Set(scope.map(t => t.task_id));

const byStatus = Object.fromEntries(STATUSES.map(s => [s, scope.filter(t => t.status === s)]));
const atRisk = scope.filter(t => t.reasons.length);
const blocked = scope.filter(t => t.status === 'Blocked');
const overdue = scope.filter(t => t.overdue);
const dueSoon = scope.filter(t => t.due_soon);

// Health rule (proposed): Red = any blocked or 2+ overdue; Amber = any overdue or due-soon; else Green.
const health = blocked.length || overdue.length >= 2 ? 'Red' : (overdue.length || dueSoon.length ? 'Amber' : 'Green');
const counts = countBy(scope);

return [{ json: {
  as_of_date: cfg.as_of_date,
  scope: { type: sprint ? 'sprint' : 'project', sprint: sprint, sprint_found: sprintFound },
  total: scope.length,
  counts,
  completion_pct: scope.length ? Math.round(counts['Done'] / scope.length * 100) : 0,
  health, health_rule: 'Red: any Blocked task or 2+ overdue. Amber: any overdue or To Do task due within ' + cfg.at_risk_days + ' days. Otherwise Green.',
  tasks_by_status: byStatus,
  blocked: blocked.map(t => t.task_id),
  overdue: overdue.map(t => t.task_id),
  at_risk: atRisk,
  upcoming_tasks: scope.filter(t => t.status !== 'Done' && t.days_to_due >= 0 && t.days_to_due <= cfg.window_days),
  project_counts: countBy(all),
  // Used by the Grounding check: what the output may and may not mention.
  scope_task_ids: [...inScopeIds],
  out_of_scope_names: sprint ? all.filter(t => !inScopeIds.has(t.task_id)).map(t => t.task_name) : []
} }];
